import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { artemisCx } from "../../../lib/utils";
import { ArtemisMorphicTooltip, ArtemisMorphicTooltipProvider } from "./02-document/morphic-tooltip";
import { DocumentPreview, INITIAL_MARKDOWN, VersionHistory, type DocumentVersion } from "./02-document/document";
export default function AiArtifactsDocument() {
    const historyId = useId();
    const [view, setView] = useState("preview");
    const [historyOpen, setHistoryOpen] = useState(false);
    const [versions, setVersions] = useState<DocumentVersion[]>([{ number: 1, markdown: INITIAL_MARKDOWN, label: "First draft" }]);
    const [selected, setSelected] = useState(1);
    const [draft, setDraft] = useState(INITIAL_MARKDOWN);
    const [announcement, setAnnouncement] = useState("");
    const current = versions.find(version => version.number === selected)!;
    const dirty = draft !== current.markdown;
    const wordCount = draft.trim() ? draft.trim().split(/\s+/).length : 0;
    const save = () => {
        const version = { number: versions.length + 1, markdown: draft, label: "Manual edit" };
        setVersions([version, ...versions]);
        setSelected(version.number);
        setAnnouncement("New version saved.");
    };
    return (<ArtemisMorphicTooltipProvider>
      <>
        <div data-slot="artifact" className="art:flex art:w-full art:min-w-0 art:flex-col art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background art:text-foreground art:mx-auto art:max-w-2xl" aria-label="Document artifact" onKeyDown={event => { if (event.key === "Escape")
        setHistoryOpen(false); }}>
          <div data-slot="artifact-header" className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:border-b art:border-border art:px-4 art:py-3">
