                <ArtemisButton variant="ghost" size="icon" type="button" className={artemisCx("art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-9 art:rounded-full", historyOpen && "art:bg-muted art:text-foreground", "art:rounded-full")} data-slot="artifact-action" aria-label="Version history" aria-expanded={historyOpen} aria-controls={historyId} onClick={() => setHistoryOpen(open => !open)} tabIndex={0}>
