            </div>
          </div>
          <div className="art:flex art:items-center art:justify-between art:gap-3 art:border-b art:border-border art:px-4 art:py-1.5">
            <div>
              <ArtemisSegmentedTabs items={[{ value: "preview", label: "Preview" }, { value: "edit", label: "Edit" }]} value={view} onValueChange={setView} ariaLabel="Document view" listClassName="art:inline-flex art:items-center art:rounded-full art:gap-0 art:bg-muted art:p-1" buttonClassName="art:rounded-full art:h-7 art:min-w-20 art:px-3 art:py-0 art:text-xs art:aria-selected:text-foreground art:focus-visible:ring-2 art:focus-visible:ring-ring"/>
