          <div data-slot="artifact-footer" className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:border-t art:border-border art:px-4 art:py-2.5">
            <span className="art:text-xs art:text-muted-foreground">
              {wordCount}
