          </div>
          <output className="art:sr-only">{announcement}</output>
        </div>
      </>
    </ArtemisMorphicTooltipProvider>);
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { ArtemisButton } from "../../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { ArtemisMorphicTooltip } from "./morphic-tooltip";
export const INITIAL_MARKDOWN = "# A calmer way to plan\n\nGood work starts with a little clarity. We\u2019re building a workspace that helps small teams turn scattered ideas into a plan everyone can follow.\n\n## Less organizing. More doing.\n\nBring your notes, decisions, and next steps together in one place. Keep the context beside the work, so nobody needs to search through yesterday\u2019s messages to understand what comes next.\n\n## Built around your day\n\nStart with an idea, shape it with your team, and leave with a clear next step. A quiet interface keeps your attention on the work while the details stay within reach.\n\n## Start small\n\nChoose one project. Invite a teammate. Write down the next three things you want to get done. That\u2019s enough to get moving.";
export type DocumentVersion = {
    number: number;
    markdown: string;
    label: string;
};
export function DocumentPreview({ markdown }: {
    markdown: string;
}) {
    return <div className="art:mx-auto art:max-w-none art:space-y-3 art:text-sm art:leading-6">
    {markdown.split(/\n{2,}/).map((block, index) => {
            if (block.startsWith("# "))
                return <h2 key={index} className="art:text-xl art:font-medium art:leading-tight art:tracking-tight">{block.slice(2)}</h2>;
            if (block.startsWith("## "))
                return <h3 key={index} className="art:pt-3 art:text-base art:font-medium">{block.slice(3)}</h3>;
            return <p key={index} className="art:whitespace-pre-wrap art:text-muted-foreground">{block}</p>;
        })}
  </div>;
}
export function VersionHistory({ id, versions, selected, dirty, onSelect, onClose }: {
    id: string;
    versions: DocumentVersion[];
    selected: number;
    dirty: boolean;
    onSelect: (version: DocumentVersion) => void;
    onClose: () => void;
}) {
    const reduce = useReducedMotion();
    return <motion.section id={id} aria-label="Version history" className="art:absolute art:inset-y-0 art:right-0 art:z-10 art:w-full art:max-w-xs art:overflow-y-auto art:border-l art:border-border art:bg-background art:p-5" initial={reduce ? false : { opacity: 0, transform: "translateX(12px)" }} animate={{ opacity: 1, transform: "translateX(0px)" }} exit={{ opacity: 0, transform: "translateX(12px)" }} transition={{ duration: reduce ? 0 : .18, ease: ARTEMIS_EASE_OUT }}>
    <div className="art:mb-4 art:flex art:items-center art:justify-between art:gap-3">
      <p className="art:text-sm art:font-medium">Version history</p>
      <ArtemisMorphicTooltip content="Close history">
        <ArtemisButton variant="ghost" size="icon" className="art:size-9" data-slot="artifact-action" aria-label="Close version history" onClick={onClose}>
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-x art:size-4" aria-hidden="true"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
        </ArtemisButton>
      </ArtemisMorphicTooltip>
    </div>
    <p className="art:mb-4 art:text-xs art:leading-5 art:text-muted-foreground">{dirty ? "Save or discard edits before switching versions." : "Open an earlier draft to review or continue from it."}</p>
    {versions.map(version => <ArtemisButton key={version.number} variant="ghost" className="art:mb-1 art:h-auto art:min-h-12 art:w-full art:justify-start art:gap-3 art:py-3" disabled={dirty} onClick={() => onSelect(version)}>
      <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-rotate-ccw art:size-3.5 art:shrink-0" aria-hidden="true"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/></svg>
      <span className="art:min-w-0 art:text-left"><span className="art:block art:text-sm">Version {version.number}</span><span className="art:block art:truncate art:text-xs art:text-muted-foreground">{version.label}</span></span>
      {selected === version.number && <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:ml-auto art:size-4 art:shrink-0" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>}
    </ArtemisButton>)}
  </motion.section>;
}

"use client";
// @zeus-internal
import { animate, motion, spring, type Transition, useMotionValue, useReducedMotion } from "motion/react";
import { createContext, type FocusEvent, type PointerEvent, type ReactNode, useCallback, useContext, useEffect, useId, useLayoutEffect, useMemo, useRef, useState, } from "react";
import { artemisCreatePortal } from "../../../../artemis-scope";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
export type TooltipSide = "top" | "bottom";
const CLOSE_DELAY = 80;
const WARM_WINDOW = 230;
const GAP = 10;
const EDGE = 12;
const INSTANT: Transition = { duration: 0 };
const WRAPPER_TRANSITION: Transition = { duration: 0.15, ease: ARTEMIS_EASE_OUT };
const MORPH_SPRING: Transition = { type: "spring", duration: 0.68, bounce: 0.22 };
const SIZE_SPRING: Transition = { type: "spring", duration: 0.76, bounce: 0.28 };
type Size = {
    width: number;
    height: number;
};
type Rect = {
    left: number;
    top: number;
    width: number;
    height: number;
};
const ESTIMATED_SIZE: Size = { width: 86, height: 30 };
type Arrival = "fresh" | "jump" | "morph";
type Tip = {
    id: string;
    content: ReactNode;
    anchor: HTMLElement;
    rect: Rect;
    instant: boolean;
    arrival: Arrival;
    seq: number;
    labelKey: number;
    side: TooltipSide;
};
type TooltipApi = {
    enter: (id: string, content: ReactNode, el: HTMLElement, side: TooltipSide) => void;
    focus: (id: string, content: ReactNode, el: HTMLElement, side: TooltipSide) => void;
    hide: (id: string) => void;
};
const TooltipContext = createContext<TooltipApi | null>(null);
function rectOf(el: HTMLElement): Rect {
    const r = el.getBoundingClientRect();
    return { left: r.left, top: r.top, width: r.width, height: r.height };
}
export function ArtemisMorphicTooltipProvider({ children, delay = 90 }: {
    children: ReactNode;
    delay?: number;
}) {
    const reduce = useReducedMotion() === true;
    const [tip, setTip] = useState<Tip | null>(null);
    const [open, setOpen] = useState(false);
    const tipRef = useRef<Tip | null>(null);
    const openRef = useRef(false);
    const seqRef = useRef(0);
    const labelKeyRef = useRef(0);
    const warmUntil = useRef(0);
    const openTimer = useRef<{
        id: string;
        handle: number;
    } | null>(null);
    const closeTimer = useRef<number | null>(null);
    const commit = useCallback((next: Tip | null) => {
        tipRef.current = next;
        setTip(next);
    }, []);
    const cancelOpen = useCallback(() => {
        if (openTimer.current)
            window.clearTimeout(openTimer.current.handle);
        openTimer.current = null;
    }, []);
    const cancelClose = useCallback(() => {
        if (closeTimer.current !== null)
            window.clearTimeout(closeTimer.current);
        closeTimer.current = null;
    }, []);
    const api = useMemo<TooltipApi>(() => {
        const reveal = (id: string, content: ReactNode, el: HTMLElement, side: TooltipSide, instant: boolean) => {
            cancelOpen();
            cancelClose();
            const prev = tipRef.current;
            seqRef.current += 1;
            const sameTrigger = prev !== null && prev.id === id;
            if (!sameTrigger || instant)
                labelKeyRef.current += 1;
            commit({
                id,
                content,
                anchor: el,
                rect: rectOf(el),
                instant,
                arrival: prev ? "jump" : "fresh",
                seq: seqRef.current,
                labelKey: labelKeyRef.current,
                side,
            });
            openRef.current = true;
            setOpen(true);
        };
        return {
            enter(id, content, el, side) {
                const current = tipRef.current;
                if (openRef.current && current) {
                    cancelClose();
                    if (current.id === id)
                        return;
                    cancelOpen();
                    seqRef.current += 1;
                    labelKeyRef.current += 1;
                    commit({ ...current, labelKey: labelKeyRef.current, id, content, anchor: el, rect: rectOf(el), instant: false, arrival: "morph", seq: seqRef.current, side });
                    return;
                }
                cancelOpen();
                if (current && performance.now() < warmUntil.current) {
                    reveal(id, content, el, side, false);
                    return;
                }
                openTimer.current = { id, handle: window.setTimeout(() => reveal(id, content, el, side, false), delay) };
            },
            focus(id, content, el, side) {
                const current = tipRef.current;
                if (openRef.current && current?.id === id) {
                    cancelClose();
                    commit({ ...current, instant: true });
                    return;
                }
                reveal(id, content, el, side, true);
            },
            hide(id) {
                if (openTimer.current?.id === id)
                    cancelOpen();
                if (!openRef.current || tipRef.current?.id !== id || closeTimer.current !== null)
                    return;
                closeTimer.current = window.setTimeout(() => {
                    closeTimer.current = null;
                    openRef.current = false;
                    warmUntil.current = performance.now() + WARM_WINDOW;
                    setOpen(false);
                    if (tipRef.current?.instant)
                        commit(null);
                }, CLOSE_DELAY);
            },
        };
    }, [cancelOpen, cancelClose, commit, delay]);
    useEffect(() => () => {
        cancelOpen();
        cancelClose();
    }, [cancelOpen, cancelClose]);
    const onExited = useCallback(() => {
        if (!openRef.current)
            commit(null);
    }, [commit]);
    return (<TooltipContext.Provider value={api}>
      {children}
      {tip ? artemisCreatePortal(<TooltipLayer tip={tip} open={open} reduce={reduce} onExited={onExited}/>, document.body) : null}
    </TooltipContext.Provider>);
}
function TooltipLayer({ tip, open, reduce, onExited }: {
    tip: Tip;
    open: boolean;
    reduce: boolean;
    onExited: () => void;
}) {
    const labelRef = useRef<HTMLDivElement>(null);
    const flushLabel = useRef<(() => void) | null>(null);
    const boxRef = useRef<HTMLDivElement>(null);
    const projecting = useRef(false);
    const mounted = useRef(performance.now());
    const [size, setSize] = useState<Size | null>(null);
    const [, setMeasurementRevision] = useState(0);
    const [, setPositionRevision] = useState(0);
    const still = reduce || tip.instant;
    const estimatedWidth = tip.content === "Version history" ? 94 : ESTIMATED_SIZE.width;
    const [positionReady, setPositionReady] = useState(tip.instant);
    const [initialPosition] = useState(() => ({ x: Math.min(Math.max(tip.rect.left + tip.rect.width / 2, EDGE + estimatedWidth / 2), window.innerWidth - EDGE - estimatedWidth / 2), y: tip.side === "bottom" ? tip.rect.top + tip.rect.height + GAP : tip.rect.top - 30 - GAP }));
    const measure = () => { const r = labelRef.current?.getBoundingClientRect(); if (r)
        setSize({ width: Math.ceil(r.width), height: Math.ceil(r.height) }); };
    useLayoutEffect(() => { measure(); }, [tip.seq, tip.arrival, tip.instant]);
    useEffect(() => {
        const positionObserver = new ResizeObserver(() => setPositionReady(true));
        if (labelRef.current)
            positionObserver.observe(labelRef.current);
        const observer = new ResizeObserver(() => {
            flushLabel.current?.();
            if (reduce && performance.now() > mounted.current && performance.now() - mounted.current < 1000 / 60 && tip.arrival === "fresh" && boxRef.current) {
                projecting.current = true;
                const initialX = Math.min(Math.max(tip.rect.left + tip.rect.width / 2, EDGE + 144), window.innerWidth - EDGE - 144);
                boxRef.current.style.transform = `translate3d(${-initialX}px, ${-(tip.side === "bottom" ? tip.rect.top + tip.rect.height + GAP : tip.rect.top - 44 - GAP)}px, 0)`;
                requestAnimationFrame(() => { projecting.current = false; if (boxRef.current)
                    boxRef.current.style.transform = "none"; });
            }
            measure();
            setPositionReady(true);
            setMeasurementRevision(v => v + 1);
        });
        const frame = requestAnimationFrame(() => { if (labelRef.current)
            observer.observe(labelRef.current); });
        return () => { cancelAnimationFrame(frame); positionObserver.disconnect(); observer.disconnect(); };
    }, [tip.seq]);
    useEffect(() => { const update = () => setPositionRevision(v => v + 1); window.addEventListener("scroll", update, true); window.addEventListener("resize", update); return () => { window.removeEventListener("scroll", update, true); window.removeEventListener("resize", update); }; }, []);
    const a = tip.anchor.isConnected ? rectOf(tip.anchor) : tip.rect;
    const half = ((positionReady || still) && size ? size.width : still ? 288 : estimatedWidth) / 2;
    const x = Math.min(Math.max(a.left + a.width / 2, EDGE + half), window.innerWidth - EDGE - half);
    const y = tip.side === "bottom" ? a.top + a.height + GAP : a.top - ((positionReady || still) && size ? size.height : still ? 44 : 30) - GAP;
    const morph = tip.arrival === "morph" && !still;
    const done = useRef({ wrapper: false, label: false });
    useEffect(() => { done.current = { wrapper: false, label: false }; }, [open]);
    const finished = (part: "wrapper" | "label") => { if (open)
        return; done.current[part] = true; if (done.current.wrapper && done.current.label)
        onExited(); };
